[InitializeOnLoad]
public static class AmazoniaTests {
 static IEnumerator routine;static float resume;static Keyboard keyboard,previous;static Key[] held=Array.Empty<Key>();static InputSettings.BackgroundBehavior oldBehavior;static bool oldBackground;
 static List<string> results=new List<string>(),errors=new List<string>();static AdventureFlow flow;static AdventurePlayer player;static AdventureBoss boss;
 static AmazoniaTests(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=Mode;}
 [MenuItem("Amazonia/Probar aventura en Play")]
 public static void Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)return;Audit();EditorSceneManager.OpenScene("Assets/Scenes/AmazoniaTerrestre.unity");SessionState.SetBool("AmazoniaTests",true);EditorApplication.isPlaying=true;}
 static void Audit(){var report=new List<string>();foreach(string scene in new[]{"AmazoniaTerrestre","AmazoniaAcuatica"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");int missing=0,broken=0,count=0;foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true)){missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);foreach(var c in t.GetComponents<Component>()){if(c==null)continue;count++;var so=new SerializedObject(c);var prop=so.GetIterator();while(prop.NextVisible(true))if(prop.propertyType==SerializedPropertyType.ObjectReference&&prop.objectReferenceValue==null&&prop.objectReferenceEntityIdValue!=default)broken++;}}report.Add(scene+": "+count+" componentes; Missing Scripts="+missing+"; Missing References="+broken);if(missing+broken>0)throw new Exception("Referencias rotas en "+scene);}File.WriteAllLines("Documentation/Amazonia/Auditoria.txt",report);}
 static void Mode(PlayModeStateChange state){if(state==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("AmazoniaTests",false)){SessionState.SetBool("AmazoniaTests",false);results.Clear();errors.Clear();previous=Keyboard.current;keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();oldBehavior=InputSystem.settings.backgroundBehavior;oldBackground=Application.runInBackground;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;Application.runInBackground=true;Application.logMessageReceived+=Log;routine=Suite();resume=0;}if(state==PlayModeStateChange.ExitingPlayMode&&routine!=null)Finish("Prueba interrumpida");}
 static void Log(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors.Add(s);}
 static void Tick(){if(!EditorApplication.isCompiling&&!EditorApplication.isUpdating&&!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists("Temp/Amazonia/test.request")){File.Delete("Temp/Amazonia/test.request");Run();}if(routine==null||!EditorApplication.isPlaying)return;if(keyboard!=null)InputSystem.QueueStateEvent(keyboard,new KeyboardState(held));if(Time.unscaledTime<resume)return;try{if(!routine.MoveNext()){Finish(null);EditorApplication.isPlaying=false;return;}resume=Time.unscaledTime+(routine.Current is float n?n:0);}catch(Exception e){Finish(e.ToString());EditorApplication.isPlaying=false;}}
 static void Finish(string error){routine=null;held=Array.Empty<Key>();Application.logMessageReceived-=Log;if(keyboard!=null)InputSystem.RemoveDevice(keyboard);keyboard=null;if(previous!=null&&previous.added)previous.MakeCurrent();InputSystem.settings.backgroundBehavior=oldBehavior;Application.runInBackground=oldBackground;Time.timeScale=1;if(error!=null)results.Add("FAIL: "+error);results.Add((errors.Count==0?"PASS: ":"FAIL: ")+"Errores en Play: "+errors.Count+" "+string.Join(" | ",errors));File.WriteAllLines("Documentation/Amazonia/Resultados.txt",new[]{DateTime.Now.ToString("s"),"Unity "+Application.unityVersion}.Concat(results));Debug.Log("AMAZONIA TESTS: "+results.Last());}
 static void Check(bool ok,string message){results.Add((ok?"PASS: ":"FAIL: ")+message);if(!ok)throw new Exception(message);}
 static void Acquire(){flow=UnityEngine.Object.FindAnyObjectByType<AdventureFlow>();player=flow.player;boss=flow.boss;}
 static void Keys(params Key[] k){held=k;InputSystem.QueueStateEvent(keyboard,new KeyboardState(k));}
 static void Place(Rigidbody2D body,Vector2 pos){body.position=pos;body.transform.position=pos;body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 static void Capture(string name){ScreenCapture.CaptureScreenshot("Documentation/Amazonia/"+name+".png");}
 static IEnumerator Suite(){
  yield return 1f;Acquire();boss.Stopped=true;Capture("01-Selva");yield return .2f;
  Check(!player.aquatic&&player.Sword&&player.Health.Current==8,"Inicio terrestre con espada y 8 HP");Check(!flow.TryDive(),"Lago bloqueado antes de vencer al jefe");
  float x=player.transform.position.x;Keys(Key.D);yield return .6f;Keys();Check(player.transform.position.x>x+2,"Camina derecha");
  Place(player.Body,new Vector2(6,.85f));x=player.transform.position.x;Keys(Key.A);yield return .5f;Keys();Check(player.transform.position.x<x-1.5f,"Camina izquierda");
  Place(player.Body,new Vector2(10,.85f));yield return .2f;Keys(Key.Space);yield return .12f;Keys();yield return .4f;Check(player.transform.position.y>2.6f,"Salto físico alcanza plataforma");yield return .7f;Check(player.Grounded&&player.transform.position.y>2.8f,"Aterriza sobre tronco");
  Place(player.Body,new Vector2(3,.85f));yield return .2f;Keys(Key.A,Key.LeftShift);yield return .23f;Keys();Check(player.transform.position.x>.45f,"Dash no atraviesa pared izquierda");yield return 1.1f;
  Place(player.Body,new Vector2(20,.85f));Keys(Key.D);yield return .05f;Keys();x=player.transform.position.x;Check(player.Dash(),"Dash disponible");Check(!player.Dash(),"Cooldown de dash impide duplicado");yield return .25f;Check(player.transform.position.x>x+2,"Dash desplaza físicamente");
  Place(player.Body,new Vector2(35,.85f));Place(boss.Body,new Vector2(37.3f,.8f));yield return .7f;int hp=boss.Health.Current;Check(player.Attack(),"Espada inicia golpe");Check(!player.Attack(),"Ataque no se duplica");yield return .4f;Check(boss.Health.Current==hp-3,"Hitbox de espada hace 3 de daño una vez");yield return .2f;Check(player.SwitchWeapon(),"Q / cambio equipa plasma");yield return .2f;
  Place(player.Body,new Vector2(34,.85f));Place(boss.Body,new Vector2(40,.8f));hp=boss.Health.Current;Check(player.Attack(),"Plasma dispara");yield return .7f;Check(boss.Health.Current==hp-1,"Proyectil físico impacta al jefe");Check(player.Health.Current==8,"Plasma no daña al dueño");
  Check(player.Health.Damage(1,new Vector2(-3,2)),"Jugador recibe daño y knockback");Check(!player.Health.Damage(1,Vector2.zero),"Invulnerabilidad bloquea daño repetido");yield return .8f;Check(player.Health.Damage(1,Vector2.zero),"Invulnerabilidad termina");yield return .8f;
  player.Health.Restore(8);player.Health.Protected=false;Place(player.Body,new Vector2(39,.85f));Place(boss.Body,new Vector2(42,.8f));boss.Stopped=false;
