  Place(player.Body,new Vector2(54,.85f));Place(boss.Body,new Vector2(38,.8f));bool thrown=false;for(float t=0;t<6;t+=.1f){if(boss.State==AdventureBoss.BossState.Rock&&UnityEngine.Object.FindObjectsByType<AdventureProjectile>().Length>0)thrown=true;yield return .1f;}Check(thrown,"Caimán lanza piedra física a distancia");Capture("02-CombateTerrestre");yield return .2f;
  boss.Stopped=true;Place(boss.Body,new Vector2(45,.8f));boss.Health.Damage(99,Vector2.zero);Check(boss.State==AdventureBoss.BossState.Stagger&&!flow.Finished,"Derrota terrestre inicia escape, no victoria");boss.Stopped=false;
  yield return 1.2f;Check(boss.State==AdventureBoss.BossState.Retreat,"Jefe recupera postura y huye");yield return 4f;Check(flow.LakeOpen&&!boss.gameObject.activeSelf,"Caimán llega al lago, se sumerge y habilita entrada");
  Place(player.Body,new Vector2(60,.85f));int carry=player.Health.Current;yield return .2f;Check(SceneManager.GetActiveScene().name=="AmazoniaTerrestre","Acercarse al lago no cambia escena automáticamente");Keys(Key.E);yield return .1f;Keys();Check(flow.Transitioning,"E inicia inmersión");yield return 2.7f;Acquire();Check(player.aquatic&&SceneManager.GetActiveScene().name=="AmazoniaAcuatica","Carga escenario acuático");Check(player.Health.Current==carry,"Conserva vida entre mapas");Check(!player.Sword&&!player.SwitchWeapon(),"Espada bloqueada bajo el agua");Check(!player.Dash(),"Dash terrestre deshabilitado bajo el agua");boss.Stopped=true;player.Health.Protected=true;Capture("03-Lago");yield return .2f;
  foreach(var key in new[]{Key.A,Key.D,Key.W,Key.S,Key.LeftArrow,Key.RightArrow,Key.UpArrow,Key.DownArrow}){Place(player.Body,new Vector2(7,8));yield return .1f;Vector2 start=player.Body.position;Keys(key);yield return .5f;Keys();Vector2 delta=player.Body.position-start;Vector2 expected=(key==Key.A||key==Key.LeftArrow)?Vector2.left:(key==Key.D||key==Key.RightArrow)?Vector2.right:(key==Key.W||key==Key.UpArrow)?Vector2.up:Vector2.down;Check(Vector2.Dot(delta,expected)>1,"Natación "+key+": "+delta+" pos="+player.Body.position+" vel="+player.Body.linearVelocity+" locked="+player.Locked);}
  Place(player.Body,new Vector2(7,8));Keys(Key.W,Key.D);yield return .6f;Keys();Check(player.Body.linearVelocity.magnitude<=player.balance.swimSpeed+.1f,"Velocidad diagonal limitada");Place(player.Body,new Vector2(7,8));yield return 1.5f;Check(player.transform.position.y<7.9f&&player.transform.position.y>7.1f,"Descenso acuático lento");
  Place(player.Body,new Vector2(1,8));Keys(Key.A);yield return .7f;Keys();Check(player.transform.position.x>.4f,"Límite acuático izquierdo");Place(player.Body,new Vector2(65,8));Keys(Key.D);yield return .7f;Keys();Check(player.transform.position.x<65.6f,"Límite acuático derecho");Place(player.Body,new Vector2(7,19));Keys(Key.W);yield return .7f;Keys();Check(player.transform.position.y<19.5f,"Techo acuático");Place(player.Body,new Vector2(7,1));Keys(Key.S);yield return .7f;Keys();Check(player.transform.position.y>.6f,"Suelo acuático");
  Place(player.Body,new Vector2(20,8));Place(boss.Body,new Vector2(27,8));Keys(Key.D);yield return .1f;Keys();yield return .3f;hp=boss.Health.Current;Check(player.Attack(),"Plasma acuático");yield return .7f;Check(boss.Health.Current==hp-1,"Plasma acuático registra daño");
  boss.Stopped=false;states.Clear();bool locked=false;Vector2 direction=Vector2.zero;
  for(float t=0;t<6;t+=.05f){states.Add(boss.State);if(boss.State!=AdventureBoss.BossState.Charge)locked=false;if(boss.State==AdventureBoss.BossState.Charge&&!locked){direction=boss.ChargeDirection;Place(player.Body,new Vector2(20,13));locked=true;}else if(boss.State==AdventureBoss.BossState.Charge&&locked)Check(Vector2.Distance(direction,boss.ChargeDirection)<.01f,"Trayectoria de embestida fija");yield return .05f;}
  Check(states.Contains(AdventureBoss.BossState.Positioning)&&states.Contains(AdventureBoss.BossState.Telegraph)&&states.Contains(AdventureBoss.BossState.Charge)&&states.Contains(AdventureBoss.BossState.Recovery),"Ciclo acuático: posición, preparación, embestida y recuperación");boss.Health.Damage(boss.Health.Current-boss.Health.maximum/2,Vector2.zero);yield return .15f;Check(boss.Enraged,"Furia a media vida");Capture("04-Furia");yield return .2f;
  player.Health.Protected=false;player.Health.Restore(8);Place(player.Body,new Vector2(20,8));Place(boss.Body,new Vector2(27,8));yield return 5f;Check(player.Health.Current<8,"Embestida acuática causa daño por contacto real");player.Health.Protected=true;flow.Pause();Check(Time.timeScale==0&&flow.Paused,"Pausa detiene simulación");yield return .1f;flow.Pause();Check(Time.timeScale==1&&!flow.Paused,"Reanuda partida");
  boss.Stopped=true;player.Body.gravityScale=0;Place(player.Body,new Vector2(20,8));Place(boss.Body,new Vector2(25,8));Keys(Key.D);yield return .1f;Keys();yield return .3f;
  for(int i=0;i<15&&!boss.Health.Dead;i++){player.Attack();yield return .55f;}Check(boss.Health.Dead,"Victoria alcanzable con plasma real; HP restante="+boss.Health.Current);yield return 1.5f;Check(flow.Finished&&flow.Won&&flow.resultPanel.activeSelf,"Victoria visible y registrada");Check(!player.Attack(),"No ataca después de victoria");Capture("05-Victoria");yield return .2f;flow.resultPanel.GetComponentInChildren<UnityEngine.UI.Button>().onClick.Invoke();yield return 1f;Acquire();Check(!player.aquatic&&player.Health.Current==8,"Reintentar reinicia aventura terrestre");boss.Stopped=true;
  player.Health.Damage(99,Vector2.zero);yield return .2f;Check(flow.Finished&&!flow.Won&&flow.resultTitle.text=="DERROTA","Derrota terrestre visible");Check(!player.Attack()&&!player.Dash(),"Muerto no ataca ni hace dash");Capture("06-Derrota");yield return .2f;Keys(Key.R);yield return .2f;Keys();yield return 1f;Acquire();Check(player.Health.Current==8&&!flow.Finished,"R reinicia tras derrota");
  SceneManager.LoadScene("AmazoniaAcuatica");yield return 1f;Acquire();boss.Stopped=true;player.Health.Damage(99,Vector2.zero);yield return .2f;Check(flow.Finished&&!flow.Won,"Derrota acuática visible");
  yield return 3.2f;Check(UnityEngine.Object.FindObjectsByType<AdventureProjectile>().Length==0,"Sin acumulación de proyectiles");
 }
